                        "title": "Attention Is All You Need",
                        "matchScore": 0.97,
                        "externalIds": {"ArXiv": "1706.03762"},
                    }
                ]
            },
            "paper/204e3073870fae3d05bcbc2f6a8e263d9b72e776/references": {
                "offset": 0,
                "next": 20,
                "data": [
                    {
                        "citedPaper": {
                            "paperId": "ref-1",
                            "title": "LSTM",
