def test_429_retries_then_succeeds(monkeypatch):
    monkeypatch.setenv("S2_API_KEY", "test-key")
    monkeypatch.setenv("S2_REQUEST_DELAY", "0")
    sleeps: list[float] = []
    attempts = {"n": 0}

    class DummyResponse:
        headers = {}
        status = 200

        def read(self, _size):
            return b'{"data":[]}'

        def __enter__(self):
            return self

        def __exit__(self, *_args):
            return False

    def fake_urlopen(request, timeout=30):
        attempts["n"] += 1
        if attempts["n"] == 1:
            raise _http_error(request.full_url, 429, b"slow down", retry_after="0")
        return DummyResponse()

    client = Client(api_key="test-key", delay=0)
    client._sleep = sleeps.append
    monkeypatch.setattr("s2_cli.transport.urllib.request.urlopen", fake_urlopen)
    payload = client.get("paper/search", {"query": "x"}).json()
    assert payload == {"data": []}
    assert attempts["n"] == 2
    assert sleeps == [0.0]


def test_429_exhausted_raises_transport_error(monkeypatch):
    monkeypatch.setenv("S2_REQUEST_DELAY", "0")

    def fake_urlopen(request, timeout=30):
        raise _http_error(request.full_url, 429, b"slow down", retry_after="0")

    client = Client(api_key="test-key", delay=0, max_retries=2)
    client._sleep = lambda _seconds: None
    monkeypatch.setattr("s2_cli.transport.urllib.request.urlopen", fake_urlopen)
    try:
        client.get("paper/search")
    except TransportError as error:
        assert "429" in str(error)
    else:
        raise AssertionError("expected TransportError")


def test_search_encodes_query(monkeypatch):
    monkeypatch.setenv("S2_API_KEY", "test-key")
    seen = {}

    class DummyResponse:
        headers = {}
        status = 200

        def read(self, _size):
            return b'{"data":[]}'

        def __enter__(self):
            return self

        def __exit__(self, *_args):
            return False

    def fake_urlopen(request, timeout=30):
        seen["url"] = request.full_url
        seen["key"] = request.headers.get("X-api-key") or request.headers.get(
            "x-api-key"
        )
        return DummyResponse()

    client = Client(api_key="secret", delay=0)
    monkeypatch.setattr("s2_cli.transport.urllib.request.urlopen", fake_urlopen)
    client.get("paper/search", {"query": "a b", "limit": 20})
    parsed = urlparse(seen["url"])
    assert parse_qs(parsed.query)["query"] == ["a b"]
    assert seen["key"] == "secret"

"""Authenticated HTTP transport for the Semantic Scholar Graph API."""

from __future__ import annotations

import json
import os
import time
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass, field
from typing import Any

from s2_cli import __version__

DEFAULT_API_URL = "https://api.semanticscholar.org/graph/v1"
MAX_RESPONSE_BYTES = 2 * 1024 * 1024
DEFAULT_REQUEST_DELAY = 1.5
DEFAULT_MAX_RETRIES = 5
TIMEOUT_SECONDS = 30


class MissingKeyError(RuntimeError):
    pass


class TransportError(RuntimeError):
    pass


class ResponseError(RuntimeError):
    pass


class NotFoundError(ResponseError):
    pass


def read_api_key() -> str:
    key = os.environ.get("PWC_SEMANTIC_SCHOLAR_API_KEY") or os.environ.get("S2_API_KEY")
    if not key or not key.strip():
        raise MissingKeyError(
            "missing API key; set PWC_SEMANTIC_SCHOLAR_API_KEY or S2_API_KEY"
        )
    return key.strip()


@dataclass(frozen=True)
class Response:
    body: bytes
    headers: dict[str, str]
    status: int = 200

    def json(self) -> Any:
        try:
            return json.loads(self.body)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise ResponseError("API returned invalid JSON") from error


@dataclass
class Client:
    api_key: str | None = None
    base_url: str = DEFAULT_API_URL
    delay: float | None = None
    max_retries: int = DEFAULT_MAX_RETRIES
    _last_request_at: float | None = field(default=None, init=False, repr=False)
    _sleep: Any = field(default=time.sleep, init=False, repr=False)

    def __post_init__(self) -> None:
        if self.api_key is None:
            self.api_key = [REDACTED]
        if self.delay is None:
            configured = os.environ.get("S2_REQUEST_DELAY")
            self.delay = (
                float(configured) if configured is not None else DEFAULT_REQUEST_DELAY
            )
        self.base_url = self.base_url.rstrip("/")

    def get(
        self, path: str, params: dict[str, object | None] | None = None
    ) -> Response:
        query = urllib.parse.urlencode(
            {
                key: value
                for key, value in (params or {}).items()
                if value is not None and value != ""
            }
        )
        url = f"{self.base_url}/{path.lstrip('/')}"
        if query:
            url += f"?{query}"
        headers = {
            "Accept": "application/json",
            "User-Agent": f"s2-cli/{__version__}",
            "x-api-key": [REDACTED] or "",
        }
        request = urllib.request.Request(url, headers=headers)
        last_error: Exception | None = None
        for attempt in range(self.max_retries):
            self._throttle()
            try:
                with urllib.request.urlopen(
                    request, timeout=TIMEOUT_SECONDS
                ) as response:
                    body = _read_bounded(response)
                    self._last_request_at = time.monotonic()
                    return Response(
                        body,
                        {key.lower(): value for key, value in response.headers.items()},
                        getattr(response, "status", 200),
                    )
            except urllib.error.HTTPError as error:
                self._last_request_at = time.monotonic()
                detail = error.read(4096).decode("utf-8", errors="replace")
                if error.code == 404:
                    raise NotFoundError(_http_message(error.code, detail)) from error
                if error.code == 429:
                    last_error = TransportError(_http_message(error.code, detail))
                    if attempt + 1 >= self.max_retries:
                        break
                    wait = _retry_after_seconds(error, self.delay or 0)
                    self._sleep(wait)
                    continue
                if 500 <= error.code < 600:
                    last_error = TransportError(_http_message(error.code, detail))
                    if attempt + 1 >= self.max_retries:
                        break
                    self._sleep(self.delay or 0)
                    continue
                raise ResponseError(_http_message(error.code, detail)) from error
            except urllib.error.URLError as error:
                self._last_request_at = time.monotonic()
                raise TransportError(f"API request failed: {error.reason}") from error
        raise last_error or TransportError("API request failed")

    def _throttle(self) -> None:
        delay = self.delay or 0
        if delay <= 0 or self._last_request_at is None:
            return
        elapsed = time.monotonic() - self._last_request_at
        remaining = delay - elapsed
        if remaining > 0:
            self._sleep(remaining)


def _read_bounded(response: Any) -> bytes:
    length = response.headers.get("Content-Length")
    if length and int(length) > MAX_RESPONSE_BYTES:
        raise ResponseError("API response exceeded the client byte limit")
    body = response.read(MAX_RESPONSE_BYTES + 1)
    if len(body) > MAX_RESPONSE_BYTES:
        raise ResponseError("API response exceeded the client byte limit")
    return body


def _http_message(status: int, detail: str) -> str:
    text = " ".join(detail.split())
    if text:
        return f"API request failed ({status}): {text}"
    return f"API request failed ({status})"


def _retry_after_seconds(error: urllib.error.HTTPError, fallback: float) -> float:
    raw = error.headers.get("Retry-After") if error.headers else None
    if raw is None:
        return max(fallback, 0)
    try:
        return max(float(raw), 0)
    except ValueError:
        return max(fallback, 0)

"""Explicit read-only parser and deterministic compact output."""

from __future__ import annotations

import argparse
import json
import sys
from typing import Any, Callable

from s2_cli import API_CONTRACT_VERSION, __version__
from s2_cli.resolve import (
    ResolvedPaper,
    arxiv_from_external_ids,
    encode_paper_path,
    resolve_paper,
)
from s2_cli.transport import (
    Client,
    MissingKeyError,
    NotFoundError,
    ResponseError,
    TransportError,
)

CITATIONS_HARD_CAP = 9999
DEFAULT_REF_FIELDS = (
    "citedPaper.paperId,citedPaper.title,citedPaper.year,"
    "citedPaper.citationCount,citedPaper.externalIds"
)
DEFAULT_CITATION_FIELDS = (
    "citingPaper.paperId,citingPaper.title,citingPaper.year,"
    "citingPaper.citationCount,citingPaper.externalIds"
)
DEFAULT_SEARCH_FIELDS = "title,year,citationCount,externalIds,url,authors,abstract"
Handler = Callable[[argparse.Namespace, Client], int]


class Parser(argparse.ArgumentParser):
    def error(self, message: str) -> None:
        self.print_usage(sys.stderr)
        self.exit(2, f"{self.prog}: error: {message}; run '{self.prog} --help'\n")


def _bounded(value: int, minimum: int, maximum: int, flag: str) -> int:
    if not minimum <= value <= maximum:
        raise argparse.ArgumentTypeError(f"{flag} must be {minimum}-{maximum}")
    return value


def _limit(maximum: int) -> Callable[[str], int]:
    return lambda value: _bounded(int(value), 1, maximum, "--limit")


def _offset(value: str) -> int:
    return _bounded(int(value), 0, 100000, "--offset")


def _clean(value: object) -> str:
    return (
        str(value if value is not None else "")
        .replace("\\", "\\\\")
        .replace("\t", "\\t")
        .replace("\r", "")
        .replace("\n", "\\n")
    )


def _emit_json(payload: Any, paper: ResolvedPaper | None = None) -> int:
    body: dict[str, Any] = {"schema_version": API_CONTRACT_VERSION, "data": payload}
    if paper is not None:
        body["paper"] = paper.as_dict()
    print(json.dumps(body, ensure_ascii=False, separators=(",", ":")))
    return 0


def _paper_from_item(item: dict[str, Any]) -> dict[str, Any]:
    return {
        "paperId": item.get("paperId"),
        "title": item.get("title"),
        "year": item.get("year"),
        "citationCount": item.get("citationCount"),
        "arxiv": arxiv_from_external_ids(item.get("externalIds")),
    }


def _print_paper_rows(items: list[dict[str, Any]]) -> None:
    print("paperId\tyear\tcites\tarxiv\ttitle")
    for item in items:
        paper = _paper_from_item(item)
        print(
            "\t".join(
                (
                    _clean(paper.get("paperId")),
                    _clean(paper.get("year")),
                    _clean(paper.get("citationCount")),
                    _clean(paper.get("arxiv")),
                    _clean(paper.get("title")),
                )
            )
        )


def _print_header(paper: ResolvedPaper) -> None:
    if paper.title:
        print(
            "# paper:\t"
            + "\t".join(
                (
                    _clean(paper.title),
                    _clean(paper.id),
                    _clean(paper.arxiv),
                    _clean(paper.match_score),
                )
            ),
            file=sys.stderr,
        )
        return
    print(f"# paper:\t{_clean(paper.id)}", file=sys.stderr)


def _print_more(payload: dict[str, Any]) -> None:
    nxt = payload.get("next")
    if nxt is None or nxt == "":
        return
    print(f"# more: rerun with --offset {nxt}", file=sys.stderr)


def _edge_items(
    payload: Any, nested_key: str
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    if not isinstance(payload, dict):
        raise ResponseError("API returned an unexpected response shape")
    values = payload.get("data")
    if not isinstance(values, list):
        raise ResponseError("API response did not contain a result list")
    items = []
    for value in values:
        if not isinstance(value, dict):
            continue
        nested = value.get(nested_key)
        if isinstance(nested, dict) and nested.get("paperId"):
            items.append(nested)
    return items, payload


def search(args: argparse.Namespace, client: Client) -> int:
    payload = client.get(
        "paper/search",
        {
            "query": args.query,
            "limit": args.limit,
            "offset": args.offset,
            "year": args.year,
            "fields": args.fields or DEFAULT_SEARCH_FIELDS,
        },
    ).json()
    if args.json:
        return _emit_json(payload)
    if not isinstance(payload, dict) or not isinstance(payload.get("data"), list):
        raise ResponseError("API response did not contain a result list")
    items = [item for item in payload["data"] if isinstance(item, dict)]
    _print_paper_rows(items)
    _print_more(payload)
    return 0


def _graph_list(
    args: argparse.Namespace,
    client: Client,
    endpoint: str,
    nested_key: str,
    default_fields: str,
) -> int:
    if endpoint == "citations" and args.offset + args.limit > CITATIONS_HARD_CAP:
        print(
            "s2: error: --offset + --limit must be <= "
            f"{CITATIONS_HARD_CAP} for citations",
            file=sys.stderr,
        )
        return 2
    paper = resolve_paper(client, args.paper)
    payload = client.get(
        f"paper/{encode_paper_path(paper.id)}/{endpoint}",
        {
            "limit": args.limit,
            "offset": args.offset,
            "fields": args.fields or default_fields,
        },
    ).json()
    if args.json:
        return _emit_json(payload, paper)
    _print_header(paper)
    items, body = _edge_items(payload, nested_key)
    _print_paper_rows(items)
    _print_more(body)
    return 0


def refs(args: argparse.Namespace, client: Client) -> int:
    return _graph_list(args, client, "references", "citedPaper", DEFAULT_REF_FIELDS)


def citations(args: argparse.Namespace, client: Client) -> int:
    return _graph_list(
        args, client, "citations", "citingPaper", DEFAULT_CITATION_FIELDS
    )


def version(_args: argparse.Namespace, _client: Client) -> int:
    print(f"s2 {__version__}\tapi {API_CONTRACT_VERSION}")
    return 0


def _json_flag(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "--json", action="store_true", help="emit stable versioned JSON"
    )


def _fields_flag(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "--fields",
        help="Semantic Scholar fields override (comma-separated)",
    )


def _add_graph_flags(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "paper",
        help="title, arXiv ID, DOI, Semantic Scholar paper ID, or URL",
    )
    parser.add_argument(
        "--limit",
        type=_limit(1000),
        default=20,
        help="results per page, 1-1000 (default: 20)",
    )
    parser.add_argument(
        "--offset",
        type=_offset,
        default=0,
        help="pagination offset (default: 0)",
    )
    _fields_flag(parser)
    _json_flag(parser)


def build_parser() -> argparse.ArgumentParser:
    parser = Parser(
        prog="s2",
        description="Read-only Semantic Scholar research CLI",
        epilog=(
            "Examples:\n"
            '  s2 refs "Attention is All You Need"\n'
            "  s2 citations ARXIV:1706.03762 --limit 50\n"
            '  s2 search "image dehazing" --year 2025-2026 --limit 100 --json'
        ),
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument(
        "--version",
        action="version",
        version=f"s2 {__version__}\tapi {API_CONTRACT_VERSION}",
    )
    commands = parser.add_subparsers(dest="command", required=True)

    search_parser = commands.add_parser(
        "search",
        help="search the Semantic Scholar graph",
        description=(
            "Relevance-search Semantic Scholar. This is a broader corpus than "
            "`pwc search`, which only returns papers already in Papers With Code."
        ),
    )
    search_parser.add_argument("query", help="title, topic, or keywords")
    search_parser.add_argument(
        "--limit",
        type=_limit(100),
        default=20,
        help="results per page, 1-100 (default: 20)",
    )
    search_parser.add_argument(
        "--offset",
        type=_offset,
        default=0,
        help="pagination offset (default: 0)",
    )
    search_parser.add_argument(
        "--year",
        help="year or inclusive range, e.g. 2025 or 2025-2026",
    )
    _fields_flag(search_parser)
    _json_flag(search_parser)
    search_parser.set_defaults(handler=search)

    refs_parser = commands.add_parser(
        "refs",
        help="list papers cited by this paper",
        description="Fetch the bibliography (outgoing references) for a paper.",
    )
    _add_graph_flags(refs_parser)
    refs_parser.set_defaults(handler=refs)

    citations_parser = commands.add_parser(
        "citations",
        help="list papers that cite this paper",
        description=(
            "Fetch incoming citations. Semantic Scholar refuses "
            f"offset+limit > {CITATIONS_HARD_CAP}; highly cited papers are not "
            "fully enumerable."
        ),
    )
    _add_graph_flags(citations_parser)
    citations_parser.set_defaults(handler=citations)

    version_parser = commands.add_parser("version", help="show CLI version")
    version_parser.set_defaults(handler=version)
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        if args.command == "version":
            return version(args, None)  # type: ignore[arg-type]
        return args.handler(args, Client())
    except MissingKeyError as error:
        print(f"s2: {error}", file=sys.stderr)
        return 2
    except TransportError as error:
        print(f"s2: {error}", file=sys.stderr)
        return 3
    except NotFoundError as error:
        print(f"s2: {error}", file=sys.stderr)
        return 4
    except ResponseError as error:
        print(f"s2: {error}", file=sys.stderr)
        return 4


if __name__ == "__main__":
    raise SystemExit(main())

"""Normalize Semantic Scholar paper identifiers and titles."""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Any
from urllib.parse import quote

from s2_cli.transport import Client, NotFoundError, ResponseError

MATCH_FIELDS = "title,year,citationCount,externalIds,url"

ARXIV_ID_RE = re.compile(
    r"^(?:arXiv:)?(\d{4}\.\d{4,5}|[a-z\-]+/\d{7})(?:v\d+)?$",
    re.IGNORECASE,
)
DOI_RE = re.compile(r"^(?:doi:)?(10\.\d{4,9}/\S+)$", re.IGNORECASE)
HEX_ID_RE = re.compile(r"^[0-9a-f]{40}$", re.IGNORECASE)
PREFIXED_RE = re.compile(
    r"^(ARXIV|DOI|CorpusId|PMID|PMCID|ACL|MAG|URL):(.+)$",
    re.IGNORECASE,
)
ARXIV_URL_RE = re.compile(
    r"^https?://(?:www\.)?arxiv\.org/(?:abs|pdf)/"
    r"(\d{4}\.\d{4,5}|[a-z\-]+/\d{7})(?:v\d+)?(?:\.pdf)?$",
    re.IGNORECASE,
)
S2_URL_RE = re.compile(
    r"^https?://(?:www\.)?semanticscholar\.org/paper/(?:[^/]+/)?"
    r"([0-9a-f]{40})/?$",
    re.IGNORECASE,
)
HTTP_URL_RE = re.compile(r"^https?://", re.IGNORECASE)


@dataclass(frozen=True)
class ResolvedPaper:
    id: str
    title: str | None = None
    arxiv: str | None = None
    match_score: float | None = None
    payload: dict[str, Any] | None = None

    def as_dict(self) -> dict[str, Any]:
        data: dict[str, Any] = {"id": self.id}
        if self.title is not None:
            data["title"] = self.title
        if self.arxiv is not None:
            data["arxiv"] = self.arxiv
        if self.match_score is not None:
            data["matchScore"] = self.match_score
        return data


def normalize_paper_id(value: str) -> str | None:
    """Return an S2 paper id if `value` looks like an identifier, else None."""
    text = value.strip()
    if not text:
        return None
    prefixed = PREFIXED_RE.fullmatch(text)
    if prefixed:
        kind, remainder = prefixed.group(1), prefixed.group(2).strip()
        if kind.upper() == "ARXIV":
            arxiv = _strip_arxiv_version(remainder)
            return f"ARXIV:{arxiv}" if arxiv else f"ARXIV:{remainder}"
        if kind.upper() == "DOI":
            return f"DOI:{remainder}"
        return f"{kind}:{remainder}"
    arxiv = ARXIV_ID_RE.fullmatch(text)
    if arxiv:
        return f"ARXIV:{_strip_arxiv_version(arxiv.group(1))}"
    doi = DOI_RE.fullmatch(text)
    if doi:
        return f"DOI:{doi.group(1)}"
    if HEX_ID_RE.fullmatch(text):
        return text.lower()
    arxiv_url = ARXIV_URL_RE.fullmatch(text)
    if arxiv_url:
        return f"ARXIV:{_strip_arxiv_version(arxiv_url.group(1))}"
    s2_url = S2_URL_RE.fullmatch(text)
    if s2_url:
        return s2_url.group(1).lower()
    if HTTP_URL_RE.match(text):
        return f"URL:{text}"
    return None


def encode_paper_path(paper_id: str) -> str:
    return quote(paper_id, safe=":")


def arxiv_from_external_ids(external_ids: Any) -> str | None:
    if not isinstance(external_ids, dict):
        return None
    value = external_ids.get("ArXiv") or external_ids.get("arxiv")
    if not value:
        return None
    return _strip_arxiv_version(str(value))


def resolve_paper(client: Client, value: str) -> ResolvedPaper:
    paper_id = normalize_paper_id(value)
    if paper_id is not None:
        return ResolvedPaper(id=paper_id)
    try:
        payload = client.get(
            "paper/search/match",
            {"query": value.strip(), "fields": MATCH_FIELDS},
        ).json()
    except NotFoundError as error:
        raise NotFoundError(f"Title match not found: {value.strip()}") from error
    paper = _match_paper(payload)
    return ResolvedPaper(
        id=str(paper["paperId"]),
        title=paper.get("title"),
        arxiv=arxiv_from_external_ids(paper.get("externalIds")),
        match_score=_match_score(paper.get("matchScore")),
        payload=paper,
    )


def _match_paper(payload: Any) -> dict[str, Any]:
    if isinstance(payload, dict):
        data = payload.get("data")
        if isinstance(data, list) and data and isinstance(data[0], dict):
            paper = data[0]
        elif payload.get("paperId"):
            paper = payload
        else:
            paper = None
        if paper and paper.get("paperId"):
            return paper
    raise ResponseError("API response did not contain a title match")


def _match_score(value: Any) -> float | None:
    if isinstance(value, (int, float)):
        return float(value)
    return None


def _strip_arxiv_version(value: str) -> str:
    return re.sub(r"v\d+$", "", value.strip(), flags=re.IGNORECASE)
